/**
 * Cobby with one face, or `winking`: smiling with both eyes open, winking every
 * few seconds and on hover (Q41; still with reduced motion, see globals.css).
 */
export function Cobby({
  face = "content",
  winking = false,
  tone = "dark",
  label,
  className,
}: {
  face?: CobbyFace
  winking?: boolean
  tone?: "dark" | "light"
  /** Spoken text; without it Cobby is decoration */
  label?: string
  className?: string
}) {
  return (
    <svg
      viewBox="0 0 180.33 187.67"
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={cn("size-16 shrink-0", tone === "light" ? "text-foam" : "text-plum", className)}
    >
      <path d={HAIR} className={tone === "light" ? "fill-smoke" : "fill-stone"} />
      {winking ? (
        <>
          {WINK_REST}
          <g className="cobby-eye">{OPEN_EYE}</g>
          <g className="cobby-wink">{WINK_EYE}</g>
        </>
      ) : (
        <g>{FACES[face]}</g>
      )}
    </svg>
  )
}
